. "$PSScriptRoot\Common.ps1"
function Register-CPAStackTasks([string]$RepoRoot) { $r=Get-CPAStackRoot; foreach($s in 'cli-proxy-api','cpa-usage-keeper'){Copy-Item "$RepoRoot\windows\tasks\Run-$($s -replace 'cli-proxy-api','CLIProxyAPI' -replace 'cpa-usage-keeper','UsageKeeper').ps1" "$r\tasks\" -Force; $n=Get-CPATaskName $s; $a=New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -ExecutionPolicy Bypass -File `"$r\tasks\Run-$($s -replace 'cli-proxy-api','CLIProxyAPI' -replace 'cpa-usage-keeper','UsageKeeper').ps1`""; $t=New-ScheduledTaskTrigger -AtStartup; Register-ScheduledTask -TaskName $n -Action $a -Trigger $t -User 'SYSTEM' -RunLevel Highest -Force|Out-Null} }
function Start-CPAStackService([string]$Service){$s=Resolve-CPAService $Service; Remove-Item (Join-Path (Get-CPAStackRoot) "state\$s.disabled") -Force -ErrorAction SilentlyContinue; Start-ScheduledTask -TaskName (Get-CPATaskName $s)}
function Stop-CPAStackService([string]$Service){$s=Resolve-CPAService $Service; New-Item -ItemType File -Force (Join-Path (Get-CPAStackRoot) "state\$s.disabled")|Out-Null; Stop-ScheduledTask -TaskName (Get-CPATaskName $s) -ErrorAction SilentlyContinue}
